import type { CatalogItem } from './catalog-item-model';
import type { Workspace } from './workspace-model';

export const CatalogItemTaskTemplateStatusKeyToLabel = {
  'Active': 'Active',
  'Inactive': 'Inactive'
} as const;
export type CatalogItemTaskTemplateStatusKey = keyof typeof CatalogItemTaskTemplateStatusKeyToLabel;

export interface CatalogItemTaskTemplate {
  /**
   * @displayName Catalog Item Task Template ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Task Title
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  taskTitle: string;
  /**
   * @displayName Assignment Group Code
   * @validationRule Required for create/update operations
   */
  assignmentGroupCode: string;
  /**
   * @displayName Catalog Item
   * @validationRule Required for create/update operations
   */
  catalogItem: Pick<CatalogItem, 'id' | 'itemName'>;
  /**
   * @displayName Description
   * @validationRule Required for create/update operations
   */
  description: string;
  /**
   * @displayName Is Required
   * @validationRule Required for create/update operations
   */
  isRequired: boolean;
  /**
   * @displayName Sort Order
   * @validationRule Required for create/update operations
   */
  sortOrder: number;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: CatalogItemTaskTemplateStatusKey;
  /**
   * @displayName Workspace
   * @validationRule Required for create/update operations
   */
  workspace: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _CatalogItemTaskTemplate = 'CatalogItemTaskTemplate' as const;